def sha(data):
    return hashlib.sha256(data).hexdigest()

def require(condition, message):
    if not condition:
        raise ValueError(message)

def inspect(root):
    require(root.is_dir() and not root.is_symlink(), "expected extracted Aurora directory")
    observed = {}
    for p in root.rglob("*"):
        require(not p.is_symlink(), "symlinks are not allowed in the input")
        if not p.is_dir():
            require(p.is_file(), "expected regular files")
            observed[p.relative_to(root).as_posix()] = sha(p.read_bytes())
    require(observed.keys() == BASE.keys(), "expected the exact list of 65 R8 files")
    swapped = {**BASE, **FINAL}
    require(observed == BASE or observed == swapped, "source differs from R8's reviewed baseline/candidate")
    return observed

def apply(root, check_only=False):
    observed = inspect(root)
    if observed == BASE:
        prepared = {}
        for rel, pairs in PATCH.items():
            path = root / rel
            data = path.read_bytes()
            require(sha(data) == BASE[rel], "source changed before patching")
            for old, new in pairs:
                a, b = old.encode(), new.encode()
                require(data.count(a) == 1, "ambiguous patch anchor in " + rel)
                data = data.replace(a, b, 1)
            require(sha(data) == FINAL[rel], "patched SHA mismatch in " + rel)
            prepared[path] = data
        if check_only:
            print("AURORA_QA:PRODUCT_OVERLAY_CHECK_ONLY:3/65")
            return
        # All source and result bytes are verified before any replacement.
        # In this disposable checkout, any I/O failure aborts the build.
        with tempfile.TemporaryDirectory(prefix=".r9-edits-", dir=root) as tmp:
            moves = []
            for i, (p, data) in enumerate(prepared.items()):
                q = Path(tmp) / str(i)
                q.write_bytes(data)
                q.chmod(stat.S_IMODE(p.stat().st_mode))
                moves.append((q, p))
            for q, p in moves:
                os.replace(q, p)
    require(inspect(root) == {**BASE, **FINAL}, "final manifest does not match the reviewed R8 candidate")
    print("AURORA_QA:PRODUCT_OVERLAY_OK:3/65")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("aurora", type=Path)
    parser.add_argument("--check-only", action="store_true")
    args = parser.parse_args()
    try:
        apply(args.aurora, args.check_only)
    except (OSError, ValueError) as e:
        parser.exit(1, f"AURORA_QA:PRODUCT_OVERLAY_REFUSED:{e}\n")
